144	        if (this.telephone == null) {
145	            return null;
146	        }
147	        String countryCode = countryCodeOf(this.telephone);
148	        if (countryCode == null) {
149	            return this.telephone;
150	        }
151	        String national = this.telephone.substring(1 + countryCode.length());
152	        StringBuilder display = new StringBuilder("+").append(countryCode);
153	        for (int i = 0; i < national.length(); i += 3) {
154	            display.append(' ').append(national, i, Math.min(i + 3, national.length()));
155	        }
156	        return display.toString();
157	    }
