239	    /**
240	     * Builds the derived identity key that consolidates all owner duplicate detection into a
241	     * single value: the normalized E.164 {@code telephone}, the lower-cased {@code email}
242	     * (empty when none) and the {@code householdId} (empty when the owner shares no household),
243	     * joined by {@code '|'}. Two owners are duplicates exactly when their whole identity keys are
244	     * equal, so a difference in any of the three parts (for example two household mates with
245	     * different telephones) yields distinct keys. A {@code null} part contributes the empty string.
246	     *
247	     * @param telephone the normalized E.164 telephone
248	     * @param email the lower-cased email, or {@code null} when none
249	     * @param householdId the shared household identifier, or {@code null} when none
250	     * @return the derived identity key
251	     */
252	    public static String identityKey(String telephone, String email, String householdId) {
253	        return (telephone == null ? "" : telephone) + "|"
254	            + (email == null ? "" : email) + "|"
255	            + (householdId == null ? "" : householdId);
256	    }
257	
258	    /**
259	     * Returns this owner's derived identity key, see
260	     * {@link #identityKey(String, String, String)}.
261	     *
262	     * @return the derived identity key for this owner
263	     */
264	    @Transient
265	    public String getIdentityKey() {
266	        return identityKey(this.telephone, this.email, this.householdId);
267	    }
268	
269	    /**
270	     * Fixed telephone country-code table: the exact national-number length (the count of digits
271	     * following the country code) each country code this application recognizes admits
272	     * ({@code '61'} Australia => 9, {@code '1'} NANP => 10). Keyed by the country-code digits
273	     * without the leading {@code '+'}. A country code absent from this table is not recognized.
274	     */
275	    private static final Map<String, Integer> COUNTRY_CODE_NATIONAL_LENGTHS = Map.of("61", 9, "1", 10);
276	
277	    /**
278	     * Resolves the recognized country code a normalized E.164 telephone carries: the longest entry
279	     * of the fixed country-code table (see {@link #COUNTRY_CODE_NATIONAL_LENGTHS}) whose digits the
280	     * number begins with, so a shorter code can never shadow a longer one. Returns the country-code
281	     * digits without the leading {@code '+'} (for example {@code '61'} for {@code '+61412345678'}),
282	     * or {@code null} when the value is {@code null}, carries no leading {@code '+'}, or begins with
283	     * no recognized country code. This is the single definition of how an E.164 telephone splits
284	     * from its country code, shared by every rule that reasons about a telephone's country code.
285	     *
286	     * @param telephone the normalized E.164 telephone (a {@code '+'} followed by digits), or {@code null}
287	     * @return the recognized country-code digits, or {@code null} when none is recognized
288	     */
289	    public static String countryCodeOf(String telephone) {
290	        if (telephone == null || !telephone.startsWith("+")) {
291	            return null;
292	        }
293	        String digits = telephone.substring(1);
294	        return COUNTRY_CODE_NATIONAL_LENGTHS.keySet().stream()
295	            .filter(digits::startsWith)
296	            .max(Comparator.comparingInt(String::length))
297	            .orElse(null);
298	    }
299	
300	    /**
301	     * Resolves the exact national-number length (the count of digits following the country code) a
302	     * recognized country code admits using the fixed country-code table ({@code '61'} => 9,
303	     * {@code '1'} => 10, see {@link #COUNTRY_CODE_NATIONAL_LENGTHS}). Returns the length, or
304	     * {@code null} when the country code is {@code null} or not recognized (it then carries no
305	     * per-country length rule). This is the single definition of the per-country national-number
306	     * lengths, shared by every rule that relates a telephone's national number to its country code.
307	     *
308	     * @param countryCode the country-code digits without the leading {@code '+'}, or {@code null}
309	     * @return the required national-number length, or {@code null} when the code is not recognized
310	     */
311	    public static Integer nationalNumberLength(String countryCode) {
312	        return countryCode == null ? null : COUNTRY_CODE_NATIONAL_LENGTHS.get(countryCode);
313	    }
314	
315	    /**
316	     * Fixed city-to-region table: the canonical region each known city belongs to
317	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}). A city
318	     * absent from this table has no known region.
319	     */
320	    private static final Map<String, String> CITY_REGIONS = Map.of(
321	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
322	
323	    /**
324	     * Resolves the canonical region a city belongs to using the fixed city-to-region table
325	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}). Returns the
326	     * region string, or {@code null} when the city has no known region. This is the single
327	     * definition of the city-to-region mapping, shared by every rule that derives a region
328	     * from an owner's city.
329	     *
330	     * @param city the city to resolve
331	     * @return the canonical region, or {@code null} when the city has no known region
332	     */
333	    public static String regionForCity(String city) {
334	        return CITY_REGIONS.get(city);
335	    }
336	
337	    /**
338	     * Fixed region-to-postcode table: the inclusive {@code {low, high}} 4-digit postcode range
339	     * each region admits ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}).
340	     * A region absent from this table has no fixed range.
341	     */
342	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
343	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
344	
345	    /**
346	     * Resolves the inclusive {@code {low, high}} 4-digit postcode range a region admits using the
347	     * fixed region-to-postcode table ({@code NSW 2000-2099}, {@code VIC 3000-3099},
348	     * {@code QLD 4000-4099}). Returns the range, or {@code null} when the region is {@code null} or
349	     * has no fixed range (any 4-digit postcode is then admitted). This is the single definition of
350	     * the region-to-postcode ranges, shared by every rule that relates a postcode to a region.
351	     *
352	     * @param region the region to resolve, or {@code null}
353	     * @return the inclusive {@code {low, high}} range, or {@code null} when the region has none
354	     */
355	    public static int[] postcodeRangeForRegion(String region) {
356	        return region == null ? null : REGION_POSTCODE_RANGES.get(region);
357	    }
358	
359	    /**
360	     * Resolves the canonical region a postcode belongs to by finding the fixed region-to-postcode
361	     * range that contains it ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}).
362	     * Returns the region string, or {@code null} when the postcode is {@code null}, not a 4-digit
363	     * value, or falls in no known range. This is the single definition of the postcode-to-region
364	     * mapping, shared by every rule that derives a region from a postcode.
365	     *
366	     * @param postcode the postcode to resolve
367	     * @return the canonical region, or {@code null} when the postcode maps to no known region
368	     */
369	    public static String regionForPostcode(String postcode) {
370	        if (postcode == null || !postcode.matches("^[0-9]{4}$")) {
371	            return null;
372	        }
373	        int value = Integer.parseInt(postcode);
374	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
375	            int[] range = entry.getValue();
376	            if (value >= range[0] && value <= range[1]) {
377	                return entry.getKey();
378	            }
379	        }
380	        return null;
381	    }
382	
383	    /**
384	     * Returns the canonical region this owner belongs to. The owner's {@code postcode} is preferred:
385	     * when it falls in a known region range (see {@link #regionForPostcode(String)}) that region is
386	     * used, disambiguating cities that share a name. Only when the postcode is absent or in no known
387	     * range does derivation fall back to the fixed city-to-region table (see
388	     * {@link #regionForCity(String)}). Returns {@code null} when neither the postcode nor the city
389	     * resolves to a known region. This is the single definition of an owner's region, shared by
390	     * every rule that derives a region from an owner.
391	     *
392	     * @return the owner's canonical region, or {@code null} when it has no known region
393	     */
394	    @Transient
395	    public String getRegion() {
396	        String region = regionForPostcode(this.postcode);
397	        return region != null ? region : regionForCity(this.city);
398	    }
399	
400	    /**
401	     * Resolves whether an {@code email} counts as present for membership purposes: the value is
402	     * non-null and not blank. Returns {@code false} otherwise. This is the single definition of an
403	     * owner "having an email", shared by every rule that turns email presence into a derived value
404	     * (its membership factor and its {@code contactPreference}).
405	     *
406	     * @param email the owner's email, or {@code null}
407	     * @return {@code true} when the email is present and not blank
408	     */
409	    public static boolean hasEmail(String email) {
410	        return email != null && !email.isBlank();
411	    }
412	
413	    /**
414	     * Resolves whether an owner with the given {@code namesakeCount} has no namesakes: the count is
415	     * present and equal to {@code 0}. Returns {@code false} when the count is {@code null} (unknown)
416	     * or positive. This is the single definition of the "no namesakes" membership factor, shared by
417	     * every rule that rewards an owner for being unique by name.
418	     *
419	     * @param namesakeCount the owner's namesake count, or {@code null}
420	     * @return {@code true} when the owner is known to have no namesakes
421	     */
422	    public static boolean hasNoNamesakes(Integer namesakeCount) {
423	        return namesakeCount != null && namesakeCount == 0;
424	    }
425	
426	    /**
427	     * Resolves whether an owner registered on {@code registrationDate} has long tenure as of
428	     * {@code asOf}: the whole number of days between the two dates exceeds {@code 365}. Returns
429	     * {@code false} when {@code registrationDate} is absent, so the owner has no derivable tenure;
430	     * because a newly created owner has zero tenure, it never counts as long-tenured. This is the
431	     * single definition of the "long tenure" membership factor, shared by every rule that rewards
432	     * an owner for tenure beyond a year.
433	     *
434	     * @param registrationDate the owner's registration date, or {@code null}
435	     * @param asOf the date the tenure is measured against
436	     * @return {@code true} when the owner's tenure exceeds 365 days
437	     */
438	    public static boolean hasLongTenure(LocalDate registrationDate, LocalDate asOf) {
439	        return registrationDate != null && ChronoUnit.DAYS.between(registrationDate, asOf) > 365;
440	    }
441	
442	    /**
443	     * Resolves whether an owner with the given {@code householdMemberCount} belongs to a large
444	     * household: the count is present and at least {@code 3}. Returns {@code false} when the count is
445	     * {@code null} (unknown) or smaller. This is the single definition of the "large household"
446	     * membership factor, shared by every rule that rewards an owner for a household of three or more.
447	     *
448	     * @param householdMemberCount the number of owners sharing the household, or {@code null}
449	     * @return {@code true} when the owner is known to belong to a household of three or more
450	     */
451	    public static boolean hasLargeHousehold(Integer householdMemberCount) {
452	        return householdMemberCount != null && householdMemberCount >= 3;
453	    }
454	
455	    /**
456	     * Returns this owner's membership points. Points start at {@code 0} and accumulate the membership
457	     * factors: {@code 2} when an email is present, {@code 1} when the owner has no namesakes
458	     * (namesakeCount is 0), {@code 2} when the owner belongs to a household of three or more, and
459	     * {@code 3} when the owner's tenure exceeds 365 days. Because a newly created owner has zero
460	     * tenure, the tenure points are never awarded on creation. This is the single source the
461	     * membership level is derived from (see {@link #getMembershipLevel()}).
462	     *
463	     * @return the owner's membership points
464	     */
465	    @Transient
466	    public Integer getMembershipPoints() {
467	        LocalDate today = LocalDate.now();
468	        int points = 0;
469	        if (hasEmail(this.email)) {
470	            points += 2;
471	        }
472	        if (hasNoNamesakes(this.namesakeCount)) {
473	            points += 1;
474	        }
475	        if (hasLargeHousehold(this.householdMemberCount)) {
476	            points += 2;
477	        }
478	        if (hasLongTenure(this.registrationDate, today)) {
479	            points += 3;
480	        }
481	        return points;
482	    }
483	
484	    /**
485	     * Returns this owner's numeric membership level, derived from its membership points (see
486	     * {@link #getMembershipPoints()}): {@code 1} for {@code 0-1} points, {@code 2} for {@code 2-3},
487	     * {@code 3} for {@code 4-5}, and {@code 4} for {@code 6} or more points.
488	     *
489	     * @return the owner's membership level
490	     */
491	    @Transient
492	    public Integer getMembershipLevel() {
493	        int points = getMembershipPoints();
494	        if (points >= 6) {
495	            return 4;
496	        }
497	        if (points >= 4) {
498	            return 3;
499	        }
500	        if (points >= 2) {
501	            return 2;
502	        }
503	        return 1;
504	    }
505	
506	    /**
507	     * Returns this owner's membership number formatted as {@code '<customerCode>-M<YY>'}, where YY is
508	     * the last two digits of the registrationDate year, e.g. {@code 'NSW-A1B2C3D4-M26'}. Returns
509	     * {@code null} when the owner has no customer code or registration date.
510	     *
511	     * @return the owner's membership number, or {@code null} when it cannot be derived
512	     */
513	    @Transient
514	    public String getMembershipNumber() {
515	        if (this.customerCode == null || this.registrationDate == null) {
516	            return null;
517	        }
518	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
519	    }
520	
521	    /**
522	     * Returns this owner's check digit: a single Luhn check digit (0-9) over the digits contained in
523	     * the owner's customerCode. Returns {@code null} when the owner has no customer code.
524	     *
525	     * @return the owner's check digit, or {@code null} when it has no customer code
526	     */
527	    @Transient
528	    public Integer getCheckDigit() {
529	        if (this.customerCode == null) {
530	            return null;
531	        }
532	        String code = this.customerCode;
533	        int sum = 0;
534	        boolean dbl = true;
535	        for (int i = code.length() - 1; i >= 0; i--) {
536	            char c = code.charAt(i);
537	            if (c < '0' || c > '9') {
538	                continue;
539	            }
540	            int d = c - '0';
541	            if (dbl) {
542	                d *= 2;
543	                if (d > 9) {
544	                    d -= 9;
545	                }
546	            }
547	            sum += d;
548	            dbl = !dbl;
549	        }
550	        return (10 - (sum % 10)) % 10;
551	    }
552	
553	    /**
554	     * Returns this owner's age band, derived from {@code birthDate} computed against
555	     * {@code registrationDate}: the whole number of years between the two dates places the owner in
556	     * {@code 'MINOR'} (under 18), {@code 'ADULT'} (18 to 64 inclusive) or {@code 'SENIOR'} (65 or
557	     * older). Returns {@code null} when the owner has no birth date or no registration date, so the
558	     * band cannot be derived. This is the single definition of an owner's age band.
559	     *
560	     * @return the owner's age band, or {@code null} when it cannot be derived
561	     */
562	    @Transient
563	    public String getAgeBand() {
564	        if (this.birthDate == null || this.registrationDate == null) {
565	            return null;
566	        }
567	        int age = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
568	        if (age < 18) {
569	            return "MINOR";
570	        }
571	        if (age < 65) {
572	            return "ADULT";
573	        }
574	        return "SENIOR";
575	    }
576	
577	    protected Set<Pet> getPetsInternal() {
578	        if (this.pets == null) {
579	            this.pets = new HashSet<>();
580	        }
581	        return this.pets;
582	    }
583	
584	    protected void setPetsInternal(Set<Pet> pets) {
585	        this.pets = pets;
586	    }
587	
588	    public List<Pet> getPets() {
589	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
590	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
591	        return Collections.unmodifiableList(sortedPets);
592	    }
593	
594	    public void setPets(List<Pet> pets) {
595	        this.pets = new HashSet<>(pets);
596	    }
597	
598	    public void addPet(Pet pet) {
599	        getPetsInternal().add(pet);
600	        pet.setOwner(this);
601	    }
602	
603	    /**
604	     * Return the Pet with the given name, or null if none found for this Owner.
605	     *
606	     * @param name to test
607	     * @return true if pet name is already in use
608	     */
609	    public Pet getPet(String name) {
610	        return getPet(name, false);
611	    }
612	
613	    /**
614	     * Return the Pet with the given name, or null if none found for this Owner.
615	     *
616	     * @param name to test
617	     * @return true if pet name is already in use
618	     */
619	    public Pet getPet(String name, boolean ignoreNew) {
620	        name = name.toLowerCase();
621	        for (Pet pet : getPetsInternal()) {
622	            if (!ignoreNew || !pet.isNew()) {
623	                String compName = pet.getName();
624	                compName = compName.toLowerCase();
625	                if (compName.equals(name)) {
626	                    return pet;
627	                }
628	            }
629	        }
630	        return null;
631	    }
632	
633	    public Pet getPet(Integer petId) {
634	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
635	    }
636	
637	    @Override
638	    public String toString() {
639	        return new ToStringCreator(this)
640	
641	            .append("id", this.getId())
642	            .append("new", this.isNew())
643	            .append("lastName", this.getLastName())
644	            .append("firstName", this.getFirstName())
645	            .append("address", this.address)
646	            .append("city", this.city)
647	            .append("telephone", this.telephone)
648	            .append("email", this.email)
649	            .toString();
650	    }
651	}
