257	    /**
258	     * Applies an owner's address to the submitted fields, normalizing it in place into the
259	     * canonical form stored and returned for the owner. This is the single intake step that owns
260	     * how a submitted address becomes an owner's stored address: it delegates every transform to
261	     * {@link #normalizeAddress(String)}, the single definition of address normalization, and writes
262	     * the results back onto {@code ownerFieldsDto}.
263	     *
264	     * <p>The structured fields are preferred when supplied: when a non-blank {@code addressLine1}
265	     * is present the two structured lines are normalized in place and the flat {@code address} is
266	     * (re)composed from them — the normalized {@code addressLine1}, with a single space and the
267	     * normalized {@code addressLine2} appended only when an {@code addressLine2} was supplied — so
268	     * every rule that later reads {@code address} sees the structured value. When no structured
269	     * {@code addressLine1} is supplied the flat {@code address} is normalized in place, preserving
270	     * backward compatibility.
271	     *
272	     * <p>It runs ahead of {@link #validateRequiredFields(OwnerFieldsDto)} so an address that is
273	     * blank after normalization in either form is rejected by the required-field check that
274	     * follows. Isolating the step here keeps {@link #prepareNewOwner(OwnerFieldsDto, LocalDate)} a
275	     * list of named intake steps and gives address handling one place to grow.
276	     *
277	     * @param ownerFieldsDto the submitted owner fields, whose address is normalized in place
278	     */
279	    private void applyAddress(OwnerFieldsDto ownerFieldsDto) {
280	        String line1 = ownerFieldsDto.getAddressLine1();
281	        if (line1 != null && !line1.isBlank()) {
282	            String normalizedLine1 = normalizeAddress(line1);
283	            ownerFieldsDto.setAddressLine1(normalizedLine1);
284	            String line2 = ownerFieldsDto.getAddressLine2();
285	            if (line2 != null && !line2.isBlank()) {
286	                String normalizedLine2 = normalizeAddress(line2);
287	                ownerFieldsDto.setAddressLine2(normalizedLine2);
288	                ownerFieldsDto.setAddress(normalizedLine1 + " " + normalizedLine2);
289	            } else {
290	                ownerFieldsDto.setAddressLine2(null);
291	                ownerFieldsDto.setAddress(normalizedLine1);
292	            }
293	        } else {
294	            ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
295	        }
296	    }
