298	    /**
299	     * Determines the effective registration date for a newly submitted owner, adjusted so it always
300	     * falls on a business day. The date supplied on the request is used when present, otherwise the
301	     * server's current date is used. When that effective date lands on a Saturday or Sunday it is
302	     * rolled forward to the following Monday; a weekday is left unchanged. This single adjusted date
303	     * is what gets stored as {@code registrationDate} and is what every value derived from it (the
304	     * membership number's year segment, the per-day create limit) is computed against.
305	     *
306	     * A supplied registration date later than the server's current date is rejected with an
307	     * {@link InvalidFieldsException}, which the exception advice renders as a 400 Bad Request.
308	     *
309	     * @param ownerFieldsDto the submitted owner fields, which may carry a registration date
310	     * @return the effective registration date rolled forward to the next business day
311	     */
312	    private LocalDate effectiveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
313	        LocalDate supplied = ownerFieldsDto.getRegistrationDate();
314	        if (supplied != null && supplied.isAfter(LocalDate.now())) {
315	            throw new InvalidFieldsException(List.of("registrationDate"));
316	        }
317	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
318	        return toBusinessDay(effective);
319	    }
320	
321	    /**
322	     * Rolls a date forward to the next business day: a Saturday or Sunday is advanced to the
323	     * following Monday, while a weekday is returned unchanged.
324	     *
325	     * @param date the date to adjust
326	     * @return the same date when it is a weekday, otherwise the next Monday
327	     */
328	    private LocalDate toBusinessDay(LocalDate date) {
329	        java.time.DayOfWeek day = date.getDayOfWeek();
330	        if (day == java.time.DayOfWeek.SATURDAY || day == java.time.DayOfWeek.SUNDAY) {
331	            return date.with(java.time.temporal.TemporalAdjusters.next(java.time.DayOfWeek.MONDAY));
332	        }
333	        return date;
334	    }
