336	    /**
337	     * The maximum number of owners that may be created on a single day. Once this many owners
338	     * already carry today's {@code registrationDate}, no further owner may be created today.
339	     */
340	    private static final long DAILY_OWNER_LIMIT = 100L;
341	
342	    /**
343	     * Rejects a new owner when {@link #DAILY_OWNER_LIMIT} or more owners already carry the given
344	     * adjusted business-day {@code registrationDate}. The count is taken against the same adjusted
345	     * date the new owner would be stored with, so owners are capped per business day. When the limit
346	     * has been reached a {@link DailyOwnerLimitExceededException} is thrown, which the exception
347	     * advice renders as a 429 Too Many Requests response.
348	     *
349	     * @param registrationDate the adjusted business-day registration date of the owner being created
350	     */
351	    private void rejectDailyLimitExceeded(LocalDate registrationDate) {
352	        if (countOwnersRegisteredOn(registrationDate) >= DAILY_OWNER_LIMIT) {
353	            throw new DailyOwnerLimitExceededException(registrationDate);
354	        }
355	    }
