357	    /**
358	     * Counts the existing owners whose adjusted business-day {@code registrationDate} equals the
359	     * given date. This is the single definition of the per-day owner count, shared by the per-day
360	     * create limit ({@link #rejectDailyLimitExceeded(LocalDate)}) and the bulk-signup warning
361	     * ({@link #bulkSignupWarning(LocalDate)}), so both accumulate owners against a day identically.
362	     *
363	     * @param registrationDate the adjusted business-day registration date to count owners against
364	     * @return the number of existing owners carrying that registration date
365	     */
366	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
367	        return this.clinicService.findAllOwners().stream()
368	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
369	            .count();
370	    }
