372	    /**
373	     * The number of owners that may carry a single day's {@code registrationDate} before that day
374	     * is flagged as a bulk-signup day. Once more than this many owners share a registration date,
375	     * the create and read responses report {@code bulkSignupWarning} true for that date.
376	     */
377	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
378	
379	    /**
380	     * Reports whether the given business-day {@code registrationDate} is a bulk-signup day, i.e.
381	     * whether more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry that date. The
382	     * count is taken against the same adjusted date owners are stored with, mirroring the
383	     * per-day create-limit accumulation. A {@code null} date is never a bulk-signup day.
384	     *
385	     * @param registrationDate the adjusted business-day registration date to test, or {@code null}
386	     * @return {@code true} when more than 80 owners share the date, otherwise {@code false}
387	     */
388	    private boolean bulkSignupWarning(LocalDate registrationDate) {
389	        if (registrationDate == null) {
390	            return false;
391	        }
392	        return countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
393	    }
