395	    /**
396	     * The maximum number of owners a single city may hold. Once a city already contains this
397	     * many owners, no further owner may be created in it.
398	     */
399	    private static final long CITY_OWNER_CAPACITY = 50L;
400	
401	    /**
402	     * Rejects a new owner whose city already contains {@link #CITY_OWNER_CAPACITY} or more owners.
403	     * Cities are compared case-insensitively, consistent with how per-city owners are counted
404	     * elsewhere. When the city is at capacity a {@link CityCapacityExceededException} is thrown,
405	     * which the exception advice renders as a 409 Conflict response.
406	     *
407	     * @param city the city of the owner being created
408	     */
409	    private void rejectCityAtCapacity(String city) {
410	        long count = this.clinicService.findAllOwners().stream()
411	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
412	            .count();
