418	    /**
419	     * Builds the customer code assigned to a newly created owner. The code is formatted as
420	     * {@code '<REGION>-<HASH8>'}, where {@code REGION} is the owner's canonical region (see
421	     * {@link Owner#getRegion()}), rendered {@code 'UNKNOWN'} when the owner has no known region,
422	     * and {@code HASH8} is the first 8 upper-case hex characters of the SHA-256 digest over the
423	     * owner's normalized E.164 {@code telephone} concatenated with its {@code lastName}. The code
424	     * carries no sequence number, so two owners sharing a region, telephone and last name resolve to
425	     * the same code. The whole owner is taken so the code is derived from whichever of its fields the
426	     * identity scheme needs.
427	     *
428	     * @param owner the owner being created, whose fields the code is derived from
429	     * @return the formatted customer code
430	     */
431	    private String customerCodeFor(Owner owner) {
432	        String region = owner.getRegion();
433	        String regionCode = region != null ? region : "UNKNOWN";
434	        String hash8 = shaHex(owner.getTelephone() + owner.getLastName(), 8);
435	        return deduplicateCustomerCode(regionCode + "-" + hash8);
436	    }
437	
438	    /**
439	     * Ensures the computed {@code customerCode} is unique across existing owners. When the given base
440	     * code collides with an existing owner's {@code customerCode}, {@code '-<n>'} is appended with the
441	     * smallest {@code n} of 2 or more that yields a code no existing owner already carries.
442	     *
443	     * @param baseCode the customer code computed for the owner being created
444	     * @return the base code when it is already unique, otherwise the de-duplicated code
445	     */
446	    private String deduplicateCustomerCode(String baseCode) {
447	        Set<String> existing = this.clinicService.findAllOwners().stream()
448	            .map(Owner::getCustomerCode)
449	            .filter(Objects::nonNull)
450	            .collect(Collectors.toSet());
451	        if (!existing.contains(baseCode)) {
452	            return baseCode;
453	        }
454	        int n = 2;
455	        while (existing.contains(baseCode + "-" + n)) {
456	            n++;
457	        }
458	        return baseCode + "-" + n;
459	    }
