461	    /**
462	     * Counts the existing owners that share the given {@code firstName} and {@code lastName}
463	     * with the owner being created, compared case-insensitively. The count is taken before the
464	     * new owner is persisted, so it reflects only pre-existing owners and never includes the new
465	     * owner itself. The resulting value is stored on the owner and exposed as {@code namesakeCount}.
466	     *
467	     * @param firstName the first name of the owner being created
468	     * @param lastName the last name of the owner being created
469	     * @return the number of pre-existing owners sharing the same first and last name
470	     */
471	    private int countNamesakes(String firstName, String lastName) {
472	        return (int) this.clinicService.findAllOwners().stream()
473	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
474	                && lastName.equalsIgnoreCase(existing.getLastName()))
475	            .count();
476	    }
