478	    /**
479	     * Flags a newly created owner as a possible (soft) duplicate. Reaching this point means the
480	     * owner already cleared {@link #rejectDuplicateIdentity(OwnerFieldsDto)}, so it is not a hard
481	     * household duplicate. A member that declared its household via {@code sharesHousehold} is a
482	     * deliberate addition to a known household, not a suspected duplicate, so it is never flagged.
483	     * Otherwise it is a possible duplicate when an existing owner shares its {@code lastName}
484	     * (compared case-insensitively) and its {@code postcode} while carrying a different (normalized)
485	     * {@code telephone}. When such an owner is found, {@code possibleDuplicate} is set {@code true}
486	     * and {@code possibleDuplicateOf} to the matching owner's id; otherwise {@code possibleDuplicate}
487	     * is set {@code false} and no matching id is recorded. An owner without a postcode can share no
488	     * postcode and is never a possible duplicate.
489	     *
490	     * @param owner the owner being created, already carrying its normalized telephone and postcode
491	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
492	     */
493	    private void applyPossibleDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
494	        owner.setPossibleDuplicate(false);
495	        owner.setPossibleDuplicateOf(null);
496	        if (sharesHousehold(ownerFieldsDto)) {
497	            return;
498	        }
499	        findPossibleDuplicate(owner).ifPresent(existing -> {
500	            owner.setPossibleDuplicate(true);
501	            owner.setPossibleDuplicateOf(existing.getId());
502	        });
503	    }
504	
505	    /**
506	     * Finds the existing owner, if any, that makes the given newly created owner a possible (soft)
507	     * duplicate: an owner sharing its {@code lastName} (compared case-insensitively) and its
508	     * {@code postcode} while carrying a different (normalized) {@code telephone}. This is the single
509	     * definition of the soft-duplicate match; {@link #applyPossibleDuplicate(Owner, OwnerFieldsDto)} only records the
510	     * outcome on the owner. An owner without a postcode can share no postcode and matches nothing, so
511	     * {@link java.util.Optional#empty()} is returned.
512	     *
513	     * @param owner the owner being created, already carrying its normalized telephone and postcode
514	     * @return the matching existing owner, or {@link java.util.Optional#empty()} when none matches
515	     */
516	    private java.util.Optional<Owner> findPossibleDuplicate(Owner owner) {
517	        if (owner.getPostcode() == null) {
518	            return java.util.Optional.empty();
519	        }
520	        return this.clinicService.findAllOwners().stream()
521	            .filter(existing -> owner.getLastName().equalsIgnoreCase(existing.getLastName())
522	                && owner.getPostcode().equals(existing.getPostcode())
523	                && !owner.getTelephone().equals(existing.getTelephone()))
524	            .findFirst();
525	    }
