527	    /**
528	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city}
529	     * or {@code telephone} is missing or blank. A field that is only whitespace is treated as
530	     * blank. When any field fails, a {@link RequiredFieldsMissingException} is thrown carrying
531	     * the names of every offending field, which the exception advice renders as a 400 response
532	     * with an {@code errors} array.
533	     *
534	     * @param ownerFieldsDto the submitted owner fields
535	     */
536	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
537	        List<String> missing = new ArrayList<>();
538	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
539	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
540	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
541	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
542	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
543	        if (!missing.isEmpty()) {
544	            throw new RequiredFieldsMissingException(missing);
545	        }
546	    }
547	
548	    private void addIfBlank(List<String> missing, String fieldName, String value) {
549	        if (value == null || value.isBlank()) {
550	            missing.add(fieldName);
551	        }
552	    }
