554	    /**
555	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets
556	     * are stripped. When a leading {@code '+'} and country code are present they are kept as
557	     * given; otherwise the country code {@code '+61'} is assumed and a single leading
558	     * {@code '0'} is dropped from the national digits. The result must be a {@code '+'}
559	     * followed by 8 to 15 digits. The normalized E.164 value is what gets stored and returned.
560	     * When the value cannot form a valid E.164 number an {@link InvalidFieldsException} is
561	     * thrown, which the exception advice renders as a 400 response naming the {@code telephone}
562	     * field. For example {@code "0412 345 678"} becomes {@code "+61412345678"}.
563	     *
564	     * @param telephone the submitted telephone value
565	     * @return the normalized E.164 telephone
566	     */
567	    private String normalizeTelephone(String telephone) {
568	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
569	        String e164;
570	        if (cleaned.startsWith("+")) {
571	            e164 = "+" + cleaned.substring(1);
572	        } else {
573	            String national = cleaned;
574	            if (national.startsWith("0")) {
575	                national = national.substring(1);
576	            }
577	            e164 = "+61" + national;
578	        }
579	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
580	            throw new InvalidFieldsException(List.of("telephone"));
581	        }
582	        validateNationalNumberLength(e164);
583	        return e164;
584	    }
585	
586	    /**
587	     * Validates the national-number length of an already syntactically valid E.164 telephone
588	     * against its country code. When the number carries a country code this application recognizes
589	     * (see {@link Owner#countryCodeOf(String)}) the digits following that code must have exactly the
590	     * length that code admits ({@code '+61'} => 9 national digits, {@code '+1'} => 10, see
591	     * {@link Owner#nationalNumberLength(String)}). When the country code is recognized but the
592	     * national number is the wrong length an {@link InvalidFieldsException} is thrown, which the
593	     * exception advice renders as a 400 response naming the {@code telephone} field. A country code
594	     * that is not recognized carries no per-country length rule and is left to the general
595	     * 8-to-15-digit E.164 check.
596	     *
597	     * @param e164 the normalized E.164 telephone (a {@code '+'} followed by digits)
598	     */
599	    private void validateNationalNumberLength(String e164) {
600	        String countryCode = Owner.countryCodeOf(e164);
601	        if (countryCode == null) {
602	            return;
603	        }
604	        int nationalLength = e164.length() - 1 - countryCode.length();
605	        if (nationalLength != Owner.nationalNumberLength(countryCode)) {
606	            throw new InvalidFieldsException(List.of("telephone"));
607	        }
608	    }
