610	    /**
611	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
612	     * and a domain containing at least one dot, none of the parts holding whitespace or a
613	     * second {@code @}.
614	     */
615	    private static final java.util.regex.Pattern EMAIL_PATTERN =
616	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
617	
618	    /**
619	     * Disposable email domains an owner may not register with. An email whose domain (compared
620	     * case-insensitively) is one of these is rejected, since it identifies a throwaway mailbox.
621	     */
622	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
623	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
624	
625	    /**
626	     * Normalizes an optional owner email. An email is optional, so a {@code null} value is
627	     * accepted and returned unchanged. When present it must be a syntactically valid address
628	     * whose domain is not on the disposable-domain blocklist (see
629	     * {@link #DISPOSABLE_EMAIL_DOMAINS}); the value is stored and returned lower-cased. When
630	     * present but syntactically invalid or on a disposable domain an
631	     * {@link InvalidFieldsException} is thrown, which the exception advice renders as a 400
632	     * response naming the {@code email} field.
633	     *
634	     * @param email the submitted email value, or {@code null} when omitted
635	     * @return the lower-cased email, or {@code null} when none was supplied
636	     */
637	    private String normalizeEmail(String email) {
638	        if (email == null) {
639	            return null;
640	        }
641	        String trimmed = email.trim();
642	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
643	            throw new InvalidFieldsException(List.of("email"));
644	        }
645	        String domain = trimmed.substring(trimmed.lastIndexOf('@') + 1).toLowerCase(java.util.Locale.ROOT);
646	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
647	            throw new InvalidFieldsException(List.of("email"));
648	        }
649	        return canonicalEmail(trimmed);
650	    }
651	
652	    /**
653	     * Reduces an email to the canonical form used both to store it and to compare it against
654	     * other owners' emails: surrounding whitespace is trimmed and the value is lower-cased. A
655	     * {@code null} email (none was supplied) canonicalizes to {@code null}. Unlike
656	     * {@link #normalizeEmail(String)} no validation is performed, so this can be applied to a
657	     * value read back off an existing owner without risk of rejecting it. This is the single
658	     * definition of email identity: two emails denote the same address exactly when they
659	     * canonicalize to the same value, so an email stored via {@link #normalizeEmail(String)} and
660	     * an email already on an existing owner can be compared for equality after both pass through
661	     * here. For example {@code "  Jane@Example.COM "} canonicalizes to {@code "jane@example.com"}.
662	     *
663	     * @param email the email to canonicalize, or {@code null} when none was supplied
664	     * @return the trimmed, lower-cased email, or {@code null} when {@code email} is {@code null}
665	     */
666	    private String canonicalEmail(String email) {
667	        if (email == null) {
668	            return null;
669	        }
670	        return email.trim().toLowerCase(java.util.Locale.ROOT);
671	    }
672	
673	    /**
674	     * Validates an optional owner postcode. A postcode is optional, so a {@code null} value is
675	     * accepted and left unchanged. When present it must be exactly 4 digits, and when the owner's
676	     * city has a known region (see {@link Owner#regionForCity(String)}) the postcode must fall
677	     * within that region's inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
678	     * {@code QLD 4000-4099}, see {@link Owner#postcodeRangeForRegion(String)}). A city with no known
679	     * region admits any 4-digit postcode. When present but malformed or out of range for the city's
680	     * region an {@link InvalidFieldsException} is thrown, which the exception advice renders as a
681	     * 400 response naming the {@code postcode} field.
682	     *
683	     * @param postcode the submitted postcode, or {@code null} when omitted
684	     * @param city the owner's city, used to resolve the region whose range the postcode must satisfy
685	     */
686	    private void validatePostcode(String postcode, String city) {
687	        if (postcode == null) {
688	            return;
689	        }
690	        if (!postcode.matches("^[0-9]{4}$")) {
691	            throw new InvalidFieldsException(List.of("postcode"));
692	        }
693	        int[] range = Owner.postcodeRangeForRegion(Owner.regionForCity(city));
694	        if (range != null) {
695	            int value = Integer.parseInt(postcode);
696	            if (value < range[0] || value > range[1]) {
697	                throw new InvalidFieldsException(List.of("postcode"));
698	            }
699	        }
700	    }
701	
702	    /**
703	     * Rejects a new owner that would join a household already occupied by an existing owner. The
704	     * household is keyed on {@code (lastName, postcode)} and identified by the deterministic
705	     * {@code householdId} the owner would receive (see {@link #householdIdFor(String, String)}), so
706	     * two owners sharing a last name and postcode belong to the same household. When any existing
707	     * owner already carries that household identifier the new owner is a household duplicate and a
708	     * {@link DuplicateIdentityException} is thrown, which the exception advice renders as a 409
709	     * Conflict response. Setting {@code sharesHousehold} declares the owner a deliberate member of
710	     * that household and bypasses this block, so it is created rather than rejected. An owner without
711	     * a postcode belongs to no shared household and is never a household duplicate.
712	     *
713	     * @param ownerFieldsDto the submitted owner fields, already normalized in place
714	     */
715	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto) {
716	        if (sharesHousehold(ownerFieldsDto)) {
717	            return;
718	        }
719	        String householdId = householdIdFor(ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode());
720	        if (householdId == null) {
721	            return;
722	        }
723	        boolean taken = this.clinicService.findAllOwners().stream()
724	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
725	        if (taken) {
726	            throw new DuplicateIdentityException(householdId);
727	        }
728	    }
729	
730	    /**
731	     * Assigns the deterministic shared {@code householdId} to a newly created owner. The identifier
732	     * is derived from the owner's household identity — its {@code lastName} and {@code postcode} (see
733	     * {@link #householdIdFor(String, String)}) — so every owner sharing a last name and postcode
734	     * resolves to the same stable value automatically, without any explicit linking. An owner without
735	     * a postcode belongs to no shared household and is left without a household identifier.
736	     *
737	     * @param owner the newly created owner, mutated in place with its household identifier
738	     */
739	    private void assignHousehold(Owner owner) {
740	        owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getPostcode()));
741	    }
742	
743	    /**
744	     * Reports whether a submitted owner opted into sharing a household, i.e. whether its request
745	     * carried {@code sharesHousehold} set to {@code true}. A {@code null} or {@code false} flag is
746	     * not opting in. This is the single reading of the {@code sharesHousehold} intent, shared by
747	     * every rule that treats a declared household member differently from an independent owner.
748	     *
749	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
750	     * @return {@code true} when the request opted into sharing a household
751	     */
752	    private boolean sharesHousehold(OwnerFieldsDto ownerFieldsDto) {
753	        return Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
754	    }
755	
756	    /**
757	     * Derives the stable {@code householdId} shared by every owner in the household identified by
758	     * the given {@code lastName} and {@code postcode}. The household is keyed on {@code (lastName,
759	     * postcode)}: the normalized last name and the postcode are hashed with SHA-256 and the leading
760	     * 12 hex characters of the digest form the identifier, so any two owners sharing a last name and
761	     * postcode — regardless of creation order or address — resolve to the same identifier
762	     * automatically. An owner without a postcode belongs to no shared household, so {@code null} is
763	     * returned.
764	     *
765	     * @param lastName the household's last name
766	     * @param postcode the household's postcode, or {@code null} when the owner has none
767	     * @return the deterministic household identifier, or {@code null} when {@code postcode} is {@code null}
768	     */
769	    private String householdIdFor(String lastName, String postcode) {
770	        if (postcode == null) {
771	            return null;
772	        }
773	        return shaHex(householdKey(lastName, postcode), 12);
774	    }
775	
776	    /**
777	     * Builds the canonical household key that identifies the household a {@code lastName} and
778	     * {@code postcode} belong to: the normalized last name (case-insensitive, with collapsed
779	     * whitespace) joined to the postcode by {@code '|'}. This is the single definition of which
780	     * owner fields make up a household and how they are normalized;
781	     * {@link #householdIdFor(String, String)} hashes this key into the stored identifier, so any two
782	     * owners in the same household resolve to the same key and therefore the same identifier.
783	     *
784	     * @param lastName the household's last name
785	     * @param postcode the household's postcode
786	     * @return the normalized household key
787	     */
788	    private String householdKey(String lastName, String postcode) {
789	        return collapseWhitespace(lastName).toLowerCase(java.util.Locale.ROOT) + "|" + postcode;
790	    }
791	
792	    /**
793	     * Computes the upper-case hex SHA-256 digest of a string, truncated to its first
794	     * {@code hexChars} characters. The input is hashed as UTF-8 bytes and each digest byte is
795	     * rendered as two upper-case hex digits, so {@code hexChars} characters cover the leading
796	     * {@code ceil(hexChars / 2)} bytes of the digest. This is the single definition of the
797	     * SHA-256 hex derivation shared by every rule that hashes owner fields (for example the
798	     * household identifier). SHA-256 is a required platform algorithm; were it ever unavailable
799	     * an {@link IllegalStateException} is thrown.
800	     *
801	     * @param input the string to hash
802	     * @param hexChars the number of leading upper-case hex characters to return
803	     * @return the first {@code hexChars} upper-case hex characters of the SHA-256 digest
804	     */
805	    private String shaHex(String input, int hexChars) {
806	        try {
807	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
808	                .digest(input.getBytes(java.nio.charset.StandardCharsets.UTF_8));
809	            StringBuilder sb = new StringBuilder();
810	            for (int i = 0; i < digest.length && sb.length() < hexChars; i++) {
811	                sb.append(String.format("%02X", digest[i]));
812	            }
813	            return sb.substring(0, hexChars);
814	        }
815	        catch (java.security.NoSuchAlgorithmException e) {
816	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
817	        }
818	    }
819	
820	    /**
821	     * Counts the owners that belong to the household identified by the given {@code householdId},
822	     * i.e. every owner carrying that exact identifier. The count is taken against the current set
823	     * of owners, so after a create it reflects the household's size including the newly persisted
824	     * owner. An owner without a household (a {@code null} identifier) belongs to no shared
825	     * household and yields {@code 0}.
826	     *
827	     * @param householdId the shared household identifier, or {@code null} when the owner shares no household
828	     * @return the number of owners in the household, or {@code 0} when {@code householdId} is {@code null}
829	     */
830	    private int countHouseholdMembers(String householdId) {
831	        if (householdId == null) {
832	            return 0;
833	        }
834	        return (int) this.clinicService.findAllOwners().stream()
835	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
836	            .count();
837	    }
838	
839	    /**
840	     * Collapses a field for household comparison: leading and trailing whitespace is trimmed and
841	     * every internal run of whitespace is reduced to a single space. A {@code null} value collapses
842	     * to the empty string. Case is left untouched so callers can compare case-insensitively.
843	     *
844	     * @param value the value to collapse, or {@code null}
845	     * @return the whitespace-collapsed value, never {@code null}
846	     */
847	    private String collapseWhitespace(String value) {
848	        if (value == null) {
849	            return "";
850	        }
851	        return value.trim().replaceAll("\\s+", " ");
852	    }
853	
854	    /**
855	     * Common street-type abbreviations expanded during address normalization, keyed by their
856	     * upper-cased token.
857	     */
858	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
859	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
860	
861	    /**
862	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
863	     * leading and trailing whitespace is trimmed, every internal run of whitespace is collapsed to
864	     * a single space, the value is upper-cased, and common street-type abbreviations are expanded
865	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value
866	     * normalizes to the empty string, and an address that holds only whitespace normalizes to the
867	     * empty string so the required-field check rejects it. For example {@code "  12  main  st "}
868	     * becomes {@code "12 MAIN STREET"}. This is the single definition of address normalization used
869	     * everywhere an address is stored or compared.
870	     *
871	     * @param address the submitted address value, or {@code null}
872	     * @return the normalized address, never {@code null}
873	     */
874	    private String normalizeAddress(String address) {
875	        if (address == null) {
876	            return "";
877	        }
878	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
879	        if (collapsed.isEmpty()) {
880	            return "";
881	        }
882	        String[] tokens = collapsed.split(" ");
883	        StringBuilder sb = new StringBuilder(collapsed.length());
884	        for (int i = 0; i < tokens.length; i++) {
885	            if (i > 0) {
886	                sb.append(' ');
887	            }
888	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
889	        }
890	        return sb.toString();
891	    }
892	}
